'use strict';
const orders = [
 {name:'토끼',avatar:'🐰',request:'풍선을 더 크게 해 주세요!',condition:'압력은 일정하게 유지해요',mode:'temperature',answer:'heat',explanation:'압력이 일정할 때 온도를 높이면 기체의 부피가 커져요.'},
 {name:'곰',avatar:'🐻',request:'풍선을 작게 만들어 주세요!',condition:'온도는 일정하게 유지해요',mode:'pressure',answer:'press',explanation:'온도가 일정할 때 압력을 높이면 기체의 부피가 작아져요.'},
 {name:'고양이',avatar:'🐱',request:'풍선을 조금 작게 해 주세요!',condition:'압력은 일정하게 유지해요',mode:'temperature',answer:'cool',explanation:'압력이 일정할 때 온도를 낮추면 기체의 부피가 작아져요.'},
 {name:'여우',avatar:'🦊',request:'풍선을 크게 만들고 싶어요!',condition:'온도는 일정하게 유지해요',mode:'pressure',answer:'release',explanation:'온도가 일정할 때 압력을 낮추면 기체의 부피가 커져요.'},
 {name:'강아지',avatar:'🐶',request:'누르는 힘으로 풍선을 작게!',condition:'온도는 일정하게 유지해요',mode:'pressure',answer:'press',explanation:'온도가 일정할 때 누르는 힘을 늘려 압력을 높이면 기체의 부피가 작아져요.'}
];
const $=id=>document.getElementById(id); const buttons=[...document.querySelectorAll('[data-action]')];
let index=0,coins=0,solved=false,attempts=0,firstCorrect=0,questionAttempts=0,runId=crypto.randomUUID();
function render(){const o=orders[index];solved=false;questionAttempts=0;$('step').textContent=`손님 ${index+1} / 5`;$('dots').innerHTML=orders.map((_,i)=>`<i class="${i<index?'done':i===index?'current':''}"></i>`).join('');$('avatar').textContent=o.avatar;$('customer').textContent=`${['첫','두','세','네','다섯'][index]} 번째 손님 · ${o.name}`;$('request').textContent=o.request;$('condition').textContent=o.condition;$('balloon').style.transform='scale(1)';$('balloon').style.filter='none';$('volume').textContent='부피: 처음 크기';$('feedback').className='feedback';$('feedback').textContent='☁️ 한 번에 한 가지 조건만 바꿔요. 기체의 양은 항상 같아요.';$('next').hidden=true;buttons.forEach(b=>{b.disabled=false;b.classList.remove('selected')});}
function choose(action){if(solved)return;attempts++;questionAttempts++;const o=orders[index];const isTemperature=action==='heat'||action==='cool';if((o.mode==='temperature')!==isTemperature){$('feedback').className='feedback wrong';$('feedback').textContent=o.mode==='temperature'?'💭 이번 주문은 압력을 일정하게 유지해야 해요. 가열이나 냉각으로 온도만 바꿔 볼까요?':'💭 이번 주문은 온도를 일정하게 유지해야 해요. 누르는 힘으로 압력만 바꿔 볼까요?';return;}
const bigger=action==='heat'||action==='release';$('balloon').style.transform=`scale(${bigger?1.22:.76})`;$('balloon').style.filter=action==='heat'?'hue-rotate(-35deg)':action==='cool'?'hue-rotate(30deg)':'none';$('volume').textContent=`부피: ${bigger?'커졌어요 ↑':'작아졌어요 ↓'}`;
if(action===o.answer){if(questionAttempts===1)firstCorrect++;solved=true;coins+=100;$('coins').textContent=coins;$('feedback').className='feedback correct';$('feedback').textContent=`✨ 주문 성공! +100 코인 · ${o.explanation}`;buttons.forEach(b=>{b.disabled=true;b.classList.toggle('selected',b.dataset.action===action)});$('next').hidden=false;$('next').textContent=index===4?'오늘의 카페 마무리 →':'다음 손님 만나기 →';}else{$('feedback').className='feedback wrong';$('feedback').textContent=`💭 ${bigger?'부피가 커졌어요. 이번 손님은 작은 풍선을 원해요.':'부피가 작아졌어요. 이번 손님은 큰 풍선을 원해요.'} 반대 방법으로 다시 실험해 보세요. 감점은 없어요!`;}}
buttons.forEach(b=>b.addEventListener('click',()=>choose(b.dataset.action)));
$('next').addEventListener('click',()=>{if(!solved)return;if(index===4){$('total').textContent=coins;$('finish').showModal();window.dispatchEvent(new CustomEvent('mongle-completed',{detail:{run_id:runId,coins,first_correct:firstCorrect,attempts:Math.min(attempts,500)}}));}else{index++;render();$('request').scrollIntoView({block:'nearest',behavior:'smooth'});}});
$('help').addEventListener('click',()=>$('concept').showModal());document.querySelector('.close').addEventListener('click',()=>$('concept').close());document.querySelector('.close-note').addEventListener('click',()=>$('concept').close());$('restart').addEventListener('click',()=>{$('finish').close();index=0;coins=0;attempts=0;firstCorrect=0;runId=crypto.randomUUID();$('coins').textContent=0;render();});render();
